head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_row = "";
scwin.noti_seq = "";
scwin.gEmpNo = js_emp_no;
scwin.corp_row;
scwin.mode;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.init();
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10801.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    for (let i = 1; i <= 10; i++) $p.getComponentById("txb_ISUR_CD" + i).hide();
    txb_NOTI_SEQ.hide();
    txb_MODE.hide();
    txb_EMP_NO.hide();
    txb_CHRG_NM.hide();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save); // 에러일경우 에러메시지 보여준다.
        scwin.afterTransmit(trs_Save);
        let fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10801.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
        await $c.win.alert("[" + gLastJob + "] 성공하였습니다.");
        let fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10801.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_EMP_NM_OnSuccess
 * @description EMP NM On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_EMP_NM_OnSuccess = function() {
    try {
        setTimeout("setChrgNM()", 700);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10801.trs_EMP_NM_OnSuccess" });
    }
};

