///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.mode = frame.opener.scwin.mode;
    if (scwin.mode === "I") {
        const sbmOptions = {
            id : "sbm_dts_Save",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Save.insertRow();
        btn_Delete.hide();
    } else {
        scwin.key_row = frame.opener.scwin.key_row;
        scwin.noti_seq = frame.opener.dts_Grid.getCellData(scwin.key_row, "NOTI_SEQ");
        await scwin.read();
    }
    txb_EMP_NO.setValue(scwin.gEmpNo);
};

/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    url += "&NOTI_SEQ=" + scwin.noti_seq;
    url += "&SCREN_ID=" + 'ULDSTF10801.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Save",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name afterExec
 * @description 담당자(내선번호)셋팅
 * @param {*} isur_cd isur_cd
 * @param {*} ld_mkt_tp_cd ld_mkt_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.afterExec = async function(isur_cd, ld_mkt_tp_cd) {
    // 담당자(내선번호)셋팅
    txb_CHRG_NM.setValue(isur_cd);
    url += "&ISUR_CD=" + isur_cd;
    const sbmOptions = {
        id : "sbm_dts_EMP_NM",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_EMP_NM=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let url = "/IntegratedBBS.do?method=registerKifrs";
    trs_EMP_NM.Action = url;
    trs_EMP_NM.KeyName = "toinb_dataid4";
    trs_EMP_NM.KeyValue = "JSP(I:pInputMaster=dts_EMP_NM)";
    trs_EMP_NM.post();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_NOTI_SEQ.getValue() === "") {
        txb_MODE.setValue("I"); // 인서트

    } else {
        txb_MODE.setValue("U"); // 업데이트

    }
    rtn = await scwin.checkForm();
    if (rtn) {
        let res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            gLastJob = "저장";
            let url = "/OnlineNotice.do?method=saveOnlineNotice" + "&SCREN_ID=" + 'ULDSTF10801.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_SAVE)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name transmit
 * @description transmit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.transmit = async function() {
    let rtn = false;
    if (txb_NOTI_SEQ.getValue() === "") {
        txb_MODE.setValue("TI"); // 전송하면서 인서트

    } else {
        txb_MODE.setValue("TU"); // 전송하면서 업데이트

    }
    rtn = await scwin.checkForm();
    if (rtn) {
        let res = window.confirm("[전송]하시겠습니까?");
        if (res) {
            gLastJob = "전송";
            let url = "/OnlineNotice.do?method=saveOnlineNotice" + "&SCREN_ID=" + 'ULDSTF10801.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            // alert(dts_MASTER.Text);
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_SAVE)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let isur_cd = "";
    let com_abbrv = "";
    let contn = "";
    let halt_yn = "";
    for (let i = 1; i <= 10; i++) {
        isur_cd = $p.getComponentById("txb_ISUR_CD" + i).getValue();
        com_abbrv = $p.getComponentById("txb_COM_ABBRV" + i).getValue();
        contn = $p.getComponentById("txb_INQDISCLS_REQ_CONTN" + i).getValue();
        halt_yn = $p.getComponentById("rdo_HALT_YN" + i).getValue();
        // if(i==1)    alert("isur_cd : " + isur_cd + " : contn : " + contn + " : online_notice_yn : " +  online_notice_yn);

        if (isur_cd !== '') {
            if (contn === '') {
                await $c.win.alert("[" + com_abbrv + "]의 '내용'을 입력해주세요.");
                return false;
            }
            if (halt_yn === '') {
                await $c.win.alert("[" + com_abbrv + "] 의 '매매거래정지여부'를 선택해주세요.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name del
 * @description del 처리
 * @returns {void}
 * @hidden N
 */
scwin.del = function() {
    txb_EMP_NO.setValue(scwin.gEmpNo);
    let res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        gLastJob = "삭제";
        let url = "/OnlineNotice.do?method=deleteOnlineNotice";
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Save)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} row_num row_num
 * @returns {void}
 * @hidden N
 */
scwin.delete = function(row_num) {
    $p.getComponentById("txb_COM_ABBRV" + row_num).setValue("");
    $p.getComponentById("txb_INQDISCLS_REQ_CONTN" + row_num).setValue("");
    $p.getComponentById("rdo_HALT_YN" + row_num).setValue('');
    $p.getComponentById("txb_ISUR_CD" + row_num).setValue("");
    $p.getComponentById("txb_CHRG_NM" + row_num).setValue("");
};

/**
 * @method
 * @name setChrgNM
 * @description set Chrg NM 처리
 * @returns {void}
 * @hidden N
 */
scwin.setChrgNM = function() {
    $p.getComponentById('txb_CHRG_NM' + scwin.corp_row).setValue(txb_CHRG_NM.getValue());
};

/**
 * @method
 * @name afterTransmit
 * @description after Transmit 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.afterTransmit = function(dtsObj) {
    const USER_DEFINE = new Array("INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            // alert("dtsObj.SrvErrMsg(USER_DEFINE[i], j) : " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            scwin.runThread(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            // setTimeout("fn_runThread('"+ dtsObj.SrvErrMsg(USER_DEFINE[i], j) + "')",30000);
            // alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j)+ "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));

        }
    }
};

/**
 * @method
 * @name runThread
 * @description run Thread 처리
 * @param {*} key key
 * @returns {void}
 * @hidden N
 */
scwin.runThread = function(key) {
    $c.frame.path("/top").runOnlineThread(key);
};
